@Tags(['slow'])
library;

import 'package:harbor/harbor.dart';
import 'package:rohd/rohd.dart';
import 'package:test/test.dart';

// PALETTE color-index context unit test. The color-index-map wavefront decodes
// each pixel's `palette_color_idx` symbol under a neighbour-derived context and
// maps the symbol through a score-ordered `color_order`. This test drives
// HarborPaletteColorContext across:
//   (a) an EXHAUSTIVE sweep of every (n, left, above-left, above) neighbour
//       combination (n in 2..8, each neighbour 0..n-1 or unavailable), and
//   (b) every real wavefront position of the palette blocks decoded from an
//       aomenc 3.12.1 screen-content keyframe (pal64_20.obu),
// checking `ctx` and `color_order` are bit-exact vs the conformant palette
// color context core. Fast: no mode-walk sim.
//
// Goldens below were captured from the reference palette color context core:
//   _sweepGold[i] = [ctx, order0..order7] for the exhaustive sweep (loop order),
//   _waveGold[i]  = [n, left, above_left, above, ctx, order0..order7] for each
//                   real wavefront position (inputs + golden together, since the
//                   inputs derive from the SW-decoded palette maps).

