void main() {
  late HarborPaletteColorContext dut;
  late Logic n, left, aboveLeft, above;

  setUp(() async {
    dut = HarborPaletteColorContext();
    n = Logic(name: 'n', width: 4);
    left = Logic(name: 'left', width: 4);
    aboveLeft = Logic(name: 'above_left', width: 4);
    above = Logic(name: 'above', width: 4);
    dut.input('n').srcConnection! <= n;
    dut.input('left').srcConnection! <= left;
    dut.input('above_left').srcConnection! <= aboveLeft;
    dut.input('above').srcConnection! <= above;
    await dut.build();
  });

  tearDown(() async {
    await Simulator.reset();
  });

  // encode a neighbour: index 0..7, or 8 = unavailable (SW -1).
  void drive(int nn, int l, int al, int a) {
    n.put(nn);
    left.put(l < 0 ? 8 : l);
    aboveLeft.put(al < 0 ? 8 : al);
    above.put(a < 0 ? 8 : a);
  }

  void checkOne(int nn, int l, int al, int a, int swCtx, List<int> swOrder) {
    drive(nn, l, al, a);
    final hwCtx = dut.output('ctx').value.toInt();
    final packed = dut.output('color_order').value.toBigInt();
    final hwOrder = [
      for (var k = 0; k < 8; k++)
        ((packed >> (k * 3)) & BigInt.from(7)).toInt(),
    ];
    // ctx == -1 marks a neighbour-score hash the AV1 spec guarantees never
    // occurs in a valid wavefront (av1_palette_color_index_context_lookup). The
    // HW output is don't-care there, so only assert ctx for reachable configs.
    if (swCtx >= 0) {
      expect(hwCtx, equals(swCtx), reason: 'ctx n=$nn L=$l AL=$al A=$a');
    }
    expect(hwOrder, equals(swOrder), reason: 'order n=$nn L=$l AL=$al A=$a');
  }

  test('exhaustive neighbour sweep: HW ctx+order == SW core', () async {
    var cases = 0;
    var gi = 0;
    for (var nn = 2; nn <= 8; nn++) {
      final vals = [for (var v = 0; v < nn; v++) v]..add(-1);
      for (final l in vals) {
        for (final al in vals) {
          for (final a in vals) {
            final g = _sweepGold[gi++];
            checkOne(nn, l, al, a, g[0], g.sublist(1));
            cases++;
          }
        }
      }
    }
    expect(cases, greaterThan(1000));
    // ignore: avoid_print
    print('exhaustive palette color ctx: $cases combos matched');
  });

  test('real wavefront positions from screen-content keyframe', () async {
    var positions = 0;
    for (final g in _waveGold) {
      checkOne(g[0], g[1], g[2], g[3], g[4], g.sublist(5));
      positions++;
    }
    expect(positions, greaterThan(200));
    // ignore: avoid_print
    print('real palette wavefront: $positions positions matched');
  });
}
